extraCSS:
html, body, body * { background: transparent !important; box-shadow: none !important; text-shadow: none !important; color: black !important; }
html, body { background: white !important; }
a[href^="http://"]::after, a[href^="https://"]::after { content: " (" attr(href) ")"; font-size: 0.85em; overflow-wrap: anywhere; }
img { max-width: 100% !important; height: auto !important; }
